import json
import websocket

import rclpy
from rclpy.node import Node
from std_msgs.msg import String


class Subscriber(Node):

    def __init__(self):
        super().__init__("subscriber")

        self.ws = websocket.WebSocket()
        self.ws.connect("ws://localhost:8080")

        self.subscription = self.create_subscription(
            String,
            "/sensor_data",
            self.receive_data,
            10
        )

        self.get_logger().info(
            "Connected to WebSocket server"
        )

    def receive_data(self, message):

        temperature, distance = map(
            int,
            message.data.split(",")
        )

        if temperature > 35:
            warning = "HIGH TEMPERATURE"

        elif distance < 20:
            warning = "TOO CLOSE"

        else:
            warning = "SAFE"

        data = {
            "type": "sensor",
            "temperature": temperature,
            "distance": distance,
            "warning": warning
        }

        self.ws.send(
            json.dumps(data)
        )

        self.get_logger().info(
            f"Sent: {data}"
        )


def main():

    rclpy.init()

    node = Subscriber()

    rclpy.spin(node)

    node.ws.close()

    node.destroy_node()

    rclpy.shutdown()


if __name__ == "__main__":
    main()